package ru.local.spbumailpilot;
import java.io.*;import java.nio.file.*;
public class UploadProgressTest {public static void main(String[] args)throws Exception{File directory=Files.createTempDirectory("upload-fixture").toFile();final long[] count={0};File file=AttachmentFiles.copy(new ByteArrayInputStream(new byte[70000]),directory,"document.pdf",100000,bytes->{if(bytes<=count[0])throw new AssertionError();count[0]=bytes;});if(count[0]!=70000||file.length()!=70000)throw new AssertionError();file.delete();try{AttachmentFiles.copy(new ByteArrayInputStream(new byte[70000]),directory,"cancel.pdf",100000,bytes->{throw new IllegalStateException("Cancelled");});throw new AssertionError();}catch(IllegalStateException expected){}if(directory.list().length!=0)throw new AssertionError("Partial upload not cleaned");directory.delete();System.out.println("PASS: upload reports actual monotonic byte counts and cleans partial file on cancellation.");}}
